import { NextRequest } from 'next/server';
import { getArtifact } from '@/infrastructure/db/business-store';
import {resolveContext,authStatus} from '@/infrastructure/auth/session';
/** Download only: content was generated by a real main Agent Skill run. */
export async function GET(_req:NextRequest,context:{params:Promise<{id:string}>}){
 try{const artifact=getArtifact((await context.params).id,resolveContext(_req));return new Response(new Uint8Array(artifact.content),{headers:{'Content-Type':artifact.mime_type,'Content-Disposition':`attachment; filename*=UTF-8''${encodeURIComponent(artifact.file_name)}`,'Cache-Control':'private, no-store'}});}catch{return Response.json({error:'Artifact not found or unauthorized'},{status:404});}
}
